import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"SQL injection (SQLi)","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/web/sql-injection.md","filePath":"d/web/sql-injection.md","lastUpdated":1781102819000}`),a={name:`d/web/sql-injection.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/web/sql-injection.md for this page in Markdown format</div><h1 id="sql-injection-sqli" tabindex="-1">SQL injection (SQLi) <a class="header-anchor" href="#sql-injection-sqli" aria-label="Permalink to “SQL injection (SQLi)”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>SQL Injection is a server-side vulnerability in web applications. It occurs when software developers create dynamic database queries that contain user input. To exploit this vulnerability, an attacker can craft user input so that the originally intended action of an SQL statement is changed. SQL injection vulnerabilities result from an application&#39;s failure to dynamically create database queries insecurely and to validate user input properly. The SQL language does not distinguish between control characters and data characters. Control characters in the data part of SQL statements must be encoded or escaped appropriately beforehand.</p><p>Attackers often detect SQL injection vulnerabilities by inserting a control character (like a single apostrophe) into the user input to place new commands not present in the original SQL statement. A simple example demonstrates this process. The following SELECT statement contains a variable userId. This statement aims to get a user&#39;s data with a specific user ID from the Users table.</p><p><code>sqlStmnt = &#39;SELECT * FROM Users WHERE UserId = &#39; + userId;</code></p><p>An attacker could now use special user input to change the original intent of the SQL statement. For example, he could use the string <code>&#39; or 1=1</code> as user input. In this case, the application would construct the following SQL statement:</p><p><code>sqlStmnt = &#39;SELECT * FROM Users WHERE UserId = &#39; + &#39; or 1=1;</code></p><p>Instead of a user&#39;s data with a specific user ID, the database returns data of all users in the table. This allows an attacker to control the SQL statement in his favor.</p><p>Several variants of SQL injection vulnerabilities, attacks, and techniques occur in different situations depending on the database system used. However, they all share that the database interprets user input as SQL commands (as in the example above). Successful SQL injection attacks can have far-reaching consequences. One would be the loss of confidentiality and integrity of the stored data. Attackers could gain read and possibly write access to sensitive data in the database. SQL injection could also compromise the authentication and authorization of the web application, allowing attackers to bypass existing access controls. In some cases, SQL injection can also be used to execute operating system commands, allowing an attacker to gain complete control over the vulnerable server.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><ul><li>Use prepared statements or stored procedures wherever possible. Prepared statements are parameterized statements and prevent attackers from manipulating SQL statements.</li><li>Validate all user input. Ensure that only expected and valid input is accepted. Do not sanitize potentially malicious input.</li><li>Reduce the potential damage of SQLi attacks. Minimize the database user&#39;s privileges using the principle of least privilege.</li><li>For detailed information and assistance on how to prevent SQL Injection vulnerabilities, see the <a href="https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP SQL Injection Prevention Cheat Sheet</a>.</li></ul>`,12)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};